// Datos del servicio de la bomba: cambia estas dos lineas despues de desplegarlo.
var base_url = "https://TU-SERVICIO.up.railway.app";
var api_key = "TU_API_KEY";

// {{nombre_coma}} = ", Nombre" o vacio, para no dejar "¡Hola, !" si WhatsApp no manda nombre.
var n = String(input.nombre || "").trim().split(/\s+/)[0];
return { base_url: base_url, api_key: api_key, nombre_coma: n ? ", " + n : "" };

