// Compara los ultimos 10 digitos: WhatsApp manda los numeros de Mexico como 521XXXXXXXXXX
// y en la tabla se pueden escribir con o sin 52/521, espacios o guiones.
function diez(t) { return String(t || "").replace(/\D/g, "").slice(-10); }
var mio = diez(input.telefono);
var lista = Array.isArray(input.lista_autorizados) ? input.lista_autorizados : [];
var ok = mio.length === 10 && lista.some(function (r) { return diez(r.telefono) === mio; });
return { autorizado: ok ? "si" : "no" };

