var t = String(input.entrada || "").trim().toLowerCase();
t = t.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, " ");
var op = "libre";
if (/^(1|encender|enciende|prender|prende|prendela|enciendela)\b/.test(t)) op = "1";
else if (/^(2|apagar|apaga|apagala)\b/.test(t)) op = "2";
else if (/^(3|estado|flujo|status|como esta)\b/.test(t)) op = "3";
else if (t === "" || /^(menu|hola|inicio|opciones|0)$/.test(t)) op = "menu";
var m = t.match(/(\d+)\s*(min|minuto|minutos)\b/);
// Mensaje por si el servicio no responde: el http_request solo sobrescribe r si la llamada sale bien.
return { opcion: op, minutos: m ? m[1] : "", r: { mensaje: "⚠️ No pude comunicarme con el equipo de la bomba. Intenta de nuevo en un momento." } };
